x = 5
if x < 10:
    if x % 2 == 0:
        print('Even')
    else:
        print('Odd')

x = 10
if x > 5:
    print('A')
elif x > 8:
    print('B')
else:
    print('C')

a = 0
if a:
    print('Non-zero')
else:
    print('Zero')

x = 3
if not x > 5:
    print('A')
elif x > 2:
    print('B')
else:
    print('C')

def test(n):
    if n > 10:
        if n % 2 == 0:
            return 'Even and large'
        else:
            return 'Odd and large'
    elif n > 5:
        if n % 2 == 0:
            return 'Even and medium'
        else:
            return 'Odd and medium'
    else:
        return 'Small'

print(test(7))
